	//         COALESCE(c.raw->>'_time_text', '')::text                     AS time_text,
	//         COALESCE((SELECT count(*) FROM video_comments rc
	//                   WHERE rc.video_id = c.video_id AND rc.parent_id = c.comment_id), 0)::bigint AS reply_count
